class METGUPNumberSequenceCleanup
{
}

Method.Source:
    /// <summary>
    /// Cleanup the GUP number sequence module
    /// </summary>
    /// <param name = "_args">Args</param>
    public static void main(Args _args)
    {

        //cleanup of Number sequence data type that needs to be removed
        NumberSequenceDatatype  NumberSequenceDatatype;

        NumberSequenceDatatype = NumberSequenceDatatype::findByDatatypeId(extendedTypeNum(METEntryId), true);

        ttsbegin;
        if(NumberSequenceDatatype)
        {
            NumberSequenceDatatype.delete();
        }
        ttscommit;

        info("@MET:Finished");
    }
